SELECT t1.id, t1.order_no, t1.payment_no, t1.payment_channel_no, t1.channel_trade_no, t1.order_type, t1.order_scene, t1.total_amount, t1.payment_amount, t1.pay_channel, t1.shop_id AS shop_id, t1.shop_name AS shop_name, t6.logo AS shop_logo, t1.status, t1.member_id, t1.total_quantity, t1.create_time, t1.source, t1.remark, t1.freight_amount, t1.cancel_time, t1.refund_time, t1.delivery_time, t1.receive_time, t1.need_delivery, t1.payment_time, t3.user_name AS receiver_name, t3.user_phone AS receiver_phone, t3.province_name AS receiver_province, t3.city_name AS receiver_city, t3.area_name AS receiver_district, t3.address AS receiver_address, t3.complete_address AS receiver_complete_address, t1.buyer_phone AS buyer_phone, t5.carrier_name AS carrier_name, t5.tracking_no AS tracking_no, t1.use_points_amount, t1.points_deduction_amount, t1.coupon_id, t1.coupon_amount FROM oms_order t1 LEFT JOIN oms_order_address t3 ON t1.id = t3.order_id AND t3.receive_address_type = 'USER_RECEIVE' LEFT JOIN oms_order_delivery t5 ON t1.id = t5.order_id LEFT JOIN pms_shop t6 ON t1.shop_id = t6.id
AND ( t1.order_no LIKE CONCAT('%', #{queryParams.keywords}, '%') OR EXISTS ( SELECT 1 FROM oms_order_item oi WHERE oi.order_id = t1.id AND oi.deleted = 0 AND (oi.sku_name LIKE CONCAT('%', #{queryParams.keywords}, '%') OR oi.spu_name LIKE CONCAT('%', #{queryParams.keywords}, '%')) ) )
AND t1.status IN
#{item}
AND t1.create_time >= #{queryParams.beginDate}
AND t1.create_time <= #{queryParams.endDate}
AND t1.delivery_time <= #{queryParams.deliveryEndDate}
AND t1.receive_time >= #{queryParams.receiveBeginDate}
AND t1.receive_time <= #{queryParams.receiveEndDate}
AND EXISTS ( SELECT 1 FROM oms_order_item oi WHERE oi.order_id = t1.id AND oi.deleted = 0 AND oi.spu_id = #{queryParams.spuId} )
AND t1.buyer_phone = #{queryParams.phone}
AND EXISTS ( SELECT 1 FROM oms_order_item oi2 WHERE oi2.order_id = t1.id AND oi2.deleted = 0 AND oi2.supplier_id = #{queryParams.supplierId} )
AND t1.member_id = #{queryParams.memberId}
AND t1.pay_channel = #{queryParams.payChannel}
AND t1.payment_no = #{queryParams.paymentNo}
AND t1.mch_id = #{queryParams.mchId}
AND t1.order_type = #{queryParams.orderType}
AND (t1.order_scene IS NULL OR t1.order_scene NOT IN
#{scene}
)
AND t1.order_scene = #{queryParams.orderScene}
and t1.deleted = 0
ORDER BY t1.create_time DESC

SELECT
sum(oi2.total_amount + oi2.freight_amount) totalAmount,
sum(t1.payment_amount) paymentAmount
FROM (

    SELECT id, order_no, status, create_time, delivery_time, receive_time,
           buyer_phone, member_id, pay_channel, payment_amount
    FROM oms_order
) t1
JOIN oms_order_item oi2 ON oi2.order_id = t1.id AND oi2.deleted = 0


        AND
        (
        t1.order_no LIKE CONCAT('%', #{queryParams.keywords}, '%')
        OR EXISTS (
            SELECT 1 FROM oms_order_item oi
            WHERE oi.order_id = t1.id AND oi.deleted = 0
              AND (oi.sku_name LIKE CONCAT('%', #{queryParams.keywords}, '%')
                   OR oi.spu_name LIKE CONCAT('%', #{queryParams.keywords}, '%'))
        )
        )


        AND t1.status IN

            #{item}



        AND t1.create_time >= #{queryParams.beginDate}


        AND t1.create_time <= #{queryParams.endDate}


        AND t1.delivery_time <= #{queryParams.deliveryEndDate}


        AND t1.receive_time >= #{queryParams.receiveBeginDate}


        AND t1.receive_time <= #{queryParams.receiveEndDate}


        AND EXISTS (
            SELECT 1 FROM oms_order_item oi
            WHERE oi.order_id = t1.id AND oi.deleted = 0
              AND oi.spu_id = #{queryParams.spuId}
        )


        AND t1.buyer_phone = #{queryParams.phone}


        AND oi2.supplier_id = #{queryParams.supplierId}


        AND t1.member_id = #{queryParams.memberId}


        AND t1.pay_channel = #{queryParams.payChannel}


        AND t1.payment_no = #{queryParams.paymentNo}


        AND t1.mch_id = #{queryParams.mchId}

    and t1.deleted = 0

ORDER BY
t1.create_time DESC

SELECT t1.id, t1.order_no, t1.payment_no, t1.payment_channel_no, t1.channel_trade_no, t1.order_type, t1.order_scene, t1.total_amount, t1.payment_amount, t1.pay_channel, t1.shop_id AS shop_id, t1.shop_name AS shop_name, t6.logo AS shop_logo, t1.status, t1.member_id, t1.freight_amount, t1.total_quantity, t1.create_time, t1.payment_time, t1.receive_time, t1.delivery_time, t1.source, t1.remark, t1.use_points_amount, t1.points_deduction_amount, t1.coupon_id, t1.coupon_amount, t3.user_name AS receiver_name, t3.user_phone AS receiver_phone, t3.province_name AS receiver_province, t3.city_name AS receiver_city, t3.area_name AS receiver_district, t3.address AS receiver_address, t3.complete_address AS receiver_complete_address, t1.buyer_phone AS buyer_phone, t5.carrier_name AS carrier_name, t5.tracking_no AS tracking_no FROM oms_order t1 LEFT JOIN oms_order_address t3 ON t1.id = t3.order_id AND t3.receive_address_type = 'USER_RECEIVE' LEFT JOIN oms_order_delivery t5 ON t1.id = t5.order_id LEFT JOIN pms_shop t6 ON t1.shop_id = t6.id
AND ( t1.order_no LIKE CONCAT('%', #{queryParams.keywords}, '%') OR EXISTS ( SELECT 1 FROM oms_order_item oi WHERE oi.order_id = t1.id AND oi.deleted = 0 AND (oi.sku_name LIKE CONCAT('%', #{queryParams.keywords}, '%') OR oi.spu_name LIKE CONCAT('%', #{queryParams.keywords}, '%')) ) )
AND t1.status IN
#{item}
AND t1.create_time >= #{queryParams.beginDate}
AND t1.create_time <= #{queryParams.endDate}
AND t1.delivery_time <= #{queryParams.deliveryEndDate}
AND t1.receive_time >= #{queryParams.receiveBeginDate}
AND t1.receive_time <= #{queryParams.receiveEndDate}
AND EXISTS ( SELECT 1 FROM oms_order_item oi WHERE oi.order_id = t1.id AND oi.deleted = 0 AND oi.spu_id = #{queryParams.spuId} )
AND t1.buyer_phone = #{queryParams.phone}
AND EXISTS ( SELECT 1 FROM oms_order_item oi2 WHERE oi2.order_id = t1.id AND oi2.deleted = 0 AND oi2.supplier_id = #{queryParams.supplierId} )
AND t1.member_id = #{queryParams.memberId}
AND t1.pay_channel = #{queryParams.payChannel}
AND t1.payment_no = #{queryParams.paymentNo}
AND t1.mch_id = #{queryParams.mchId}
AND t1.order_type = #{queryParams.orderType}
AND t1.order_scene = #{queryParams.orderScene}
and t1.deleted = 0
ORDER BY t1.create_time DESC
